/*
 * The live EPS authority chart for features/steering.md.
 *
 * Replaces the static <img> inside #zp-torque-live with an inline,
 * theme-aware SVG when JavaScript is available; without JS the static
 * baked SVG (steering-torque.svg) stays. All geometry comes from
 * window.ZP_TORQUE_DATA, generated by the site repo's
 * scripts/gen-wiki-chart.mjs — this file never carries numbers.
 *
 * Loaded site-wide through extra_javascript; it exits immediately on
 * pages without the mount.
 */
(function () {
  "use strict";

  var data = window.ZP_TORQUE_DATA;
  var mount = document.getElementById("zp-torque-live");
  if (!data || !mount) return;

  var view = data.view;
  var NS = "http://www.w3.org/2000/svg";

  function el(name, attrs, text) {
    var node = document.createElementNS(NS, name);
    for (var k in attrs) node.setAttribute(k, attrs[k]);
    if (text != null) node.textContent = text;
    return node;
  }

  /* np.interp with flat clamps — same semantics as chart-geometry.js */
  function interp(bp, vals, v) {
    if (v <= bp[0]) return vals[0];
    if (v >= bp[bp.length - 1]) return vals[vals.length - 1];
    var i = 0;
    while (v > bp[i + 1]) i++;
    var t = (v - bp[i]) / (bp[i + 1] - bp[i]);
    return vals[i] + t * (vals[i + 1] - vals[i]);
  }
  var ceiling = function (v) {
    return interp(data.ceilBp, data.ceilV, v);
  };
  var px = function (v) {
    return view.x0 + (v / data.vMax) * (view.x1 - view.x0);
  };
  var py = function (c) {
    return (
      view.y1 -
      ((c - data.cMin) / (data.cMax - data.cMin)) *
        (view.y1 - view.y0)
    );
  };
  /* v from a pointer x, clamped into the drawn range */
  var vx = function (pxv) {
    var v =
      ((pxv - view.x0) / (view.x1 - view.x0)) * data.vMax;
    return Math.max(0, Math.min(data.vMax, v));
  };

  var svg = el("svg", {
    viewBox: "0 0 " + view.w + " " + view.h,
    role: "img",
    "aria-label":
      "Available steering torque from the EPS across speed, up to " +
      "40 mph. zoompilot tracks the measured EPS ceiling, up to " +
      data.gapPct + "% more torque than stock openpilot's flat 800 " +
      "cap. Move a pointer over the chart for values.",
  });
  svg.classList.add("tc-live");

  svg.appendChild(
    el("rect", {
      x: 0.5, y: 0.5, width: view.w - 1, height: view.h - 1, rx: 14,
      class: "tc-panel",
    }),
  );

  data.yTicks.forEach(function (c) {
    svg.appendChild(
      el("line", {
        x1: view.x0, x2: view.x1, y1: py(c), y2: py(c),
        class: "tc-grid",
      }),
    );
    svg.appendChild(
      el("text", { x: view.x0 - 8, y: py(c) + 4, "text-anchor": "end", class: "tc-text" },
        String(c)),
    );
  });

  data.xTicks.forEach(function (t) {
    svg.appendChild(
      el("line", {
        x1: px(t.v), x2: px(t.v), y1: view.y1, y2: view.y1 + 4,
        class: "tc-axis",
      }),
    );
    svg.appendChild(
      el("text", { x: px(t.v), y: view.y1 + 18, "text-anchor": "middle", class: "tc-text" },
        String(t.mph)),
    );
  });

  /* the shaded band between the lines: the torque stock strands */
  svg.appendChild(el("path", { d: data.paths.gap, class: "tc-gap-fill" }));

  /* the +torque gap callout */
  var gapLabelY = py(980);
  var gap = el("text", {
    x: px(data.gapV) + 8, y: gapLabelY, class: "tc-text tc-small",
  });
  var t1 = el("tspan", { x: px(data.gapV) + 8, dy: 0 }, "up to");
  var t2 = el("tspan", { x: px(data.gapV) + 8, dy: 13 }, data.gapPct + "% more torque");
  var t3 = el("tspan", { x: px(data.gapV) + 8, dy: 13, class: "tc-tag" }, "with no hardware mods");
  gap.appendChild(t1);
  gap.appendChild(t2);
  gap.appendChild(t3);
  svg.appendChild(gap);

  svg.appendChild(el("path", { d: data.paths.stock, class: "tc-stock" }));
  svg.appendChild(el("text", { x: view.x0 + 8, y: py(data.stockCap) + 16, class: "tc-label" }, "stock openpilot"));
  svg.appendChild(el("path", { d: data.paths.zpShared, class: "tc-zp tc-zp-shared" }));
  svg.appendChild(el("path", { d: data.paths.zp, class: "tc-zp" }));
  svg.appendChild(el("text", { x: view.x0 + 8, y: py(data.ceilV[0]) - 8, class: "tc-label tc-zp-text" }, "zoompilot"));

  svg.appendChild(el("line", { x1: view.x0, x2: view.x1, y1: view.y1, y2: view.y1, class: "tc-axis" }));
  svg.appendChild(el("line", { x1: view.x0, x2: view.x0, y1: view.y0, y2: view.y1, class: "tc-axis" }));
  svg.appendChild(el("text", { x: view.x1, y: view.y1 + 31, "text-anchor": "end", class: "tc-text tc-tiny" }, "speed · mph"));
  /* centered over the y tick numbers (right-aligned at view.x0 - 8) */
  svg.appendChild(el("text", {
    x: view.x0 - 21, y: 11, "text-anchor": "middle", class: "tc-text tc-tiny",
  }, "torque"));

  /* hover crosshair: hidden until a pointer enters the plot */
  var cursor = el("line", { y1: view.y0, y2: view.y1, class: "tc-cursor", visibility: "hidden" });
  var dotZp = el("circle", { r: 3.2, class: "tc-dot-zp", visibility: "hidden" });
  var dotStock = el("circle", { r: 3.2, class: "tc-dot-stock", visibility: "hidden" });
  var tip = el("text", { class: "tc-tip", visibility: "hidden" });
  var tipBg = el("rect", { rx: 6, class: "tc-tip-bg", visibility: "hidden" });
  svg.appendChild(cursor);
  svg.appendChild(dotStock);
  svg.appendChild(dotZp);
  svg.appendChild(tipBg);
  svg.appendChild(tip);

  function move(event) {
    var rect = svg.getBoundingClientRect();
    var scale = view.w / rect.width;
    var xpx = (event.clientX - rect.left) * scale;
    var v = vx(xpx);
    var cxp = px(v);
    var cZp = ceiling(v);
    var cStock = Math.min(data.stockCap, cZp);
    cursor.setAttribute("x1", cxp);
    cursor.setAttribute("x2", cxp);
    dotZp.setAttribute("cx", cxp);
    dotZp.setAttribute("cy", py(cZp));
    dotStock.setAttribute("cx", cxp);
    dotStock.setAttribute("cy", py(cStock));
    var mph = Math.round((v / data.mphToMs) * 10) / 10;
    var lines = [
      "mph " + mph.toFixed(0),
      "zoompilot " + Math.round(cZp),
      "stock " + Math.round(cStock),
    ];
    while (tip.firstChild) tip.removeChild(tip.firstChild);
    lines.forEach(function (line, i) {
      tip.appendChild(
        el("tspan", { x: 0, dy: i === 0 ? 0 : 13, class: i === 1 ? "tc-zp-text" : null }, line),
      );
    });
    /* flip the tooltip to the right side near the plot's left edge */
    var flip = cxp < view.x0 + 110;
    var tx = flip ? cxp + 10 : cxp - 100;
    tip.setAttribute("transform", "translate(" + (tx + 6) + " " + (view.y0 + 14) + ")");
    tipBg.setAttribute("x", tx);
    tipBg.setAttribute("y", view.y0 + 6);
    tipBg.setAttribute("width", 92);
    tipBg.setAttribute("height", 46);
    [cursor, dotZp, dotStock, tip, tipBg].forEach(function (n) {
      n.setAttribute("visibility", "visible");
    });
  }

  function leave() {
    [cursor, dotZp, dotStock, tip, tipBg].forEach(function (n) {
      n.setAttribute("visibility", "hidden");
    });
  }

  svg.addEventListener("pointermove", move);
  svg.addEventListener("pointerleave", leave);

  /* swap the static <img> for the live chart */
  mount.replaceChildren(svg);

  /* draw-in: the zoompilot line traces on first view, unless the
   * visitor asked for reduced motion */
  var reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduced) return;
  var zpPath = svg.querySelector(".tc-zp:not(.tc-zp-shared)");
  if (!zpPath) return;
  var len = zpPath.getTotalLength();
  zpPath.style.strokeDasharray = String(len);
  zpPath.style.strokeDashoffset = String(len);
  var draw = function () {
    zpPath.style.transition = "stroke-dashoffset 1.4s ease-out";
    zpPath.style.strokeDashoffset = "0";
  };
  if ("IntersectionObserver" in window) {
    var seen = false;
    new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting && !seen) {
          seen = true;
          draw();
          obs.disconnect();
        }
      });
    }).observe(svg);
  } else {
    draw();
  }
})();
